-- SAGED: Tabela alimentos_pnae (584 alimentos PNAE/FNDE)
-- Execute no Supabase SQL Editor

CREATE TABLE IF NOT EXISTS public.alimentos_pnae (
  id SERIAL PRIMARY KEY,
  code TEXT UNIQUE NOT NULL,
  name TEXT NOT NULL,
  category TEXT DEFAULT 'Outros',
  unit TEXT DEFAULT 'kg',
  kcal_per_100g NUMERIC DEFAULT 0,
  protein_per_100g NUMERIC DEFAULT 0,
  fat_per_100g NUMERIC DEFAULT 0,
  carb_per_100g NUMERIC DEFAULT 0,
  calcium_per_100g NUMERIC DEFAULT 0,
  iron_per_100g NUMERIC DEFAULT 0,
  sodium_per_100g NUMERIC DEFAULT 0,
  stock NUMERIC DEFAULT 0,
  avg_consume NUMERIC DEFAULT 0,
  days_left INTEGER DEFAULT 0,
  family_farm BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT now()
);

ALTER TABLE public.alimentos_pnae ENABLE ROW LEVEL SECURITY;
CREATE POLICY "anon_select_alimentos" ON public.alimentos_pnae FOR SELECT USING (true);
CREATE POLICY "anon_insert_alimentos" ON public.alimentos_pnae FOR INSERT WITH CHECK (true);
CREATE POLICY "anon_update_alimentos" ON public.alimentos_pnae FOR UPDATE USING (true);












